 const[sourceCheck,setSourceCheck]=useState(null),[checkingSources,setCheckingSources]=useState(false);
 const checkAllSources=async(activate=false)=>{setCheckingSources(true);setError('');try{const response=await fetch('/api/admin/sources/check-all'+(activate?'?activate=true':''),{method:'POST',headers:auth()});const data=await response.json();if(!response.ok)throw Error(data.error||'HTTP '+response.status);setSourceCheck(data);if(activate)await dashboard()}catch(e){setError(t('تعذر فحص المصادر: ','Source check failed: ')+e.message)}finally{setCheckingSources(false)}};

 const[searchText,setSearchText]=useState(''),[selectedCategory,setSelectedCategory]=useState('all'),[selectedCountry,setSelectedCountry]=useState('all'),[selectedSource,setSelectedSource]=useState('all');
 const[sourceCountryFilter,setSourceCountryFilter]=useState('all'),[sourceNameFilter,setSourceNameFilter]=useState('all');
 const[adminCountryFilter,setAdminCountryFilter]=useState('all'),[selectedRegion,setSelectedRegion]=useState('all'),[adminRegion,setAdminRegion]=useState('all');
 const[newsPages,setNewsPages]=useState({pending:1,published:1,rejected:1}),[newsTables,setNewsTables]=useState({});
 const loadNewsTable=async(group,pageNumber=1)=>{if(!adminToken)return;try{const qs=new URLSearchParams({status:group,region:adminRegion,country:adminCountryFilter,page:String(pageNumber),pageSize:'30'});const r=await fetch('/api/admin/articles/page?'+qs,{headers:auth()});if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();setNewsTables(prev=>({...prev,[group]:data}))}catch(e){setError(e.message)}};
 useEffect(()=>{if(adminToken){['pending','published'].forEach(group=>loadNewsTable(group,newsPages[group]))}},[adminToken,adminRegion,adminCountryFilter,newsPages.pending,newsPages.published,newsPages.rejected]);
 const[features,setFeatures]=useState([]),[adminFeatures,setAdminFeatures]=useState([]),[featureForm,setFeatureForm]=useState({id:0,kind:'article',title:'',body:'',excerpt:'',coverUrl:'',published:false}),[activeFeature,setActiveFeature]=useState(null);
 const loadFeatures=()=>fetch('/api/features').then(r=>r.ok?r.json():[]).then(setFeatures).catch(()=>{});
