 <div className="section-heading newsroom-heading"><h2>{selectedCategory==='all'?t('أبرز الأخبار','Featured stories'):(ar?categoryNames[selectedCategory]:selectedCategory)}</h2><span>{t('تغطية متنوعة من المصادر الأصلية','Curated from original sources')}</span></div>
